head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92022.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    MxTab_1.setSelectedTabIndex(0);
    scwin.setComNmGrid(grd_ComNm, dlt_comNm);
    scwin.setIsuNmGrid(grd_IsuNm, dlt_isuNm);
    scwin.setStkKndCdGrid(grd_StkKndCd, dlt_stkKndCd);
    scwin.setSymblGrid(grd_Symbl, dlt_symbl);
    scwin.setShrtCdGrid(grd_ShrtCd, dlt_shrtCd);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setComNmGrid
 * @description 20100408(목) 김봉석대리요청(전화) 1.회사명 : 5번 추가 2.종목명 : 영문명입력시 대소문자구분 -> 대문자만 입력 으로 변경
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setComNmGrid = function (grdObj, dtsObj) {
    // var vHeadString = "COM_TYP:STRING(500),COM_NM:STRING(500),COM_NM_SIZE:STRING(500)";
    // dtsObj.SetDataHeader(vHeadString);
    scwin.setComNmDataSet(dtsObj, 0, '한글회사명', '삼성전자(주)', '한글30자');
    scwin.setComNmDataSet(dtsObj, 1, '한글회사약명', '삼성전자', '한글15자');
    scwin.setComNmDataSet(dtsObj, 2, '영문회사명', 'SAMSUNG ELECTRONICS CO.,LTD', '영문60자');
    scwin.setComNmDataSet(dtsObj, 3, '영문회사약명', 'SAMSUNG ELEC', '영문30자');
    scwin.setComNmDataSet(dtsObj, 4, '영문회사심볼', 'SEC', '영문대문자 6자');
};

/**
 * @method
 * @name setComNmDataSet
 * @description 회사명 안내 데이터 행 추가
 * @param {*} dtsObj dtsObj
 * @param {Number} idx idx
 * @param {*} val_1 val_1
 * @param {*} val_2 val_2
 * @param {*} val_3 val_3
 * @returns {void}
 * @hidden N
 */
scwin.setComNmDataSet = function (dtsObj, idx, val_1, val_2, val_3) {
    dtsObj.insertRow();
    dtsObj.setCellData(idx, "comTyp", val_1);
    dtsObj.setCellData(idx, "comNm", val_2);
    dtsObj.setCellData(idx, "comNmSize", val_3);
};

/**
 * @method
 * @name setIsuNmGrid
 * @description 종목명 안내 그리드 데이터 구성
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setIsuNmGrid = function (grdObj, dtsObj) {
    // var vHeadString = "isuKorNm:STRING(500),isuKorAbbrv:STRING(500),isuEngNm:STRING(500),isuEngAbbrv:STRING(500),isuEngSymbl:STRING(500),ISU_NM_SIZE:STRING(500)";
    // dtsObj.SetDataHeader(vHeadString);
    scwin.setIsuNmDataSet(dtsObj, 0, '하나은행보통주', '하나은행', 'HanaBank', 'HanaBk', 'HNB', '한글종목명(한글30자)');
    scwin.setIsuNmDataSet(dtsObj, 1, '하나은행1우선주', '하나은행우', 'HanaBank(1P)', 'HanaBk(1P)', 'HNB5', '한글종목약명(한글15자)');
    scwin.setIsuNmDataSet(dtsObj, 2, '하나은행2우선주', '하나은행2우', 'HanaBank(2P)', 'HanaBk(2P)', 'HNB7', '영문종목명(영문60자)');
    scwin.setIsuNmDataSet(dtsObj, 3, '하나은행3우선주(신형)', '하나은행3우B', 'HanaBank(3PB)', 'HanaBk(3PB)', 'HNB9', '영문종목약명(영문30자)');
};

/**
 * @method
 * @name setIsuNmDataSet
 * @description 종목명 안내 데이터 행 추가
 * @param {*} dtsObj dtsObj
 * @param {Number} idx idx
 * @param {*} val_1 val_1
 * @param {*} val_2 val_2
 * @param {*} val_3 val_3
 * @param {*} val_4 val_4
 * @param {*} val_5 val_5
 * @param {*} val_6 val_6
 * @returns {void}
 * @hidden N
 */
scwin.setIsuNmDataSet = function (dtsObj, idx, val_1, val_2, val_3, val_4, val_5, val_6) {
    dtsObj.insertRow();
    dtsObj.setCellData(idx, "isuKorNm", val_1);
    dtsObj.setCellData(idx, "isuKorAbbrv", val_2);
    dtsObj.setCellData(idx, "isuEngNm", val_3);
    dtsObj.setCellData(idx, "isuEngAbbrv", val_4);
    dtsObj.setCellData(idx, "isuEngSymbl", val_5);
    dtsObj.setCellData(idx, "isuNmSize", val_6);
};

/**
 * @method
 * @name setStkKndCdGrid
 * @description 주식종류코드 안내 그리드 데이터 구성
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setStkKndCdGrid = function (grdObj, dtsObj) {
    // var vHeadString = "isuKorNm:STRING(500),isuKorAbbrv:STRING(500),isuEngNm:STRING(500),isuEngAbbrv:STRING(500),REMK:STRING(500)";
    // dtsObj.SetDataHeader(vHeadString);
    scwin.setStkKndCdDataSet(dtsObj, 0, '보통주', '없음', '없음', '없음', '');
    scwin.setStkKndCdDataSet(dtsObj, 1, '보통1신주', '1', '(1N)', '(1N)', '');
    scwin.setStkKndCdDataSet(dtsObj, 2, '보통2신주', '2', '(2N)', '(2N)', '');
    scwin.setStkKndCdDataSet(dtsObj, 3, '보통1전환1신주', '전1', '(1C1N)', '(1C1N)', '');
    scwin.setStkKndCdDataSet(dtsObj, 4, '보통1전환2신주', '전2', '(1C2N)', '(1C2N)', '');
    scwin.setStkKndCdDataSet(dtsObj, 5, '1우선주', '우', '(1P)', '(1P)', '');
    scwin.setStkKndCdDataSet(dtsObj, 6, '1우선주(신형)', '우B', '(1PB)', '(1PB)', '신형우선주');
    scwin.setStkKndCdDataSet(dtsObj, 7, '1우선1신주', '우1', '(1P1N)', '(1P1N)', '');
    scwin.setStkKndCdDataSet(dtsObj, 8, '2우선주(신형)', '2우B', '(2PB)', '(2PB)', '신형우선주');
};

/**
 * @method
 * @name setStkKndCdDataSet
 * @description 주식종류코드 안내 데이터 행 추가
 * @param {*} dtsObj dtsObj
 * @param {Number} idx idx
 * @param {*} val_1 val_1
 * @param {*} val_2 val_2
 * @param {*} val_3 val_3
 * @param {*} val_4 val_4
 * @param {*} val_5 val_5
 * @returns {void}
 * @hidden N
 */
scwin.setStkKndCdDataSet = function (dtsObj, idx, val_1, val_2, val_3, val_4, val_5) {
    dtsObj.insertRow();
    dtsObj.setCellData(idx, "isuKorNm", val_1);
    dtsObj.setCellData(idx, "isuKorAbbrv", val_2);
    dtsObj.setCellData(idx, "isuEngNm", val_3);
    dtsObj.setCellData(idx, "isuEngAbbrv", val_4);
    dtsObj.setCellData(idx, "remk", val_5);
};

/**
 * @method
 * @name setSymblGrid
 * @description 영문심볼 안내 그리드 데이터 구성
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setSymblGrid = function (grdObj, dtsObj) {
    // var vHeadString = "isuKorNm:STRING(500),isuEngSymbl:STRING(500)";
    // dtsObj.SetDataHeader(vHeadString);
    scwin.setSymblDataSet(dtsObj, 0, '하나은행보통주', 'HNB');
    scwin.setSymblDataSet(dtsObj, 1, '하나은행보통1신주', 'HNB1');
    scwin.setSymblDataSet(dtsObj, 2, '하나은행보통2신주', 'HNB2');
    scwin.setSymblDataSet(dtsObj, 3, '하나은행보통3신주', 'HNB3');
    scwin.setSymblDataSet(dtsObj, 4, '하나은행보통4신주', 'HNB4');
    scwin.setSymblDataSet(dtsObj, 5, '하나은행1우선주 / 1우선주(신형)', 'HNB5');
    scwin.setSymblDataSet(dtsObj, 6, '하나은행1우선주(신주)', 'HNB6');
    scwin.setSymblDataSet(dtsObj, 7, '하나은행2우선주 / 2우선주(신형)', 'HNB7');
    scwin.setSymblDataSet(dtsObj, 8, '하나은행2우선주(신주) ', 'HNB8');
    scwin.setSymblDataSet(dtsObj, 9, '하나은행3우선주', 'HNB9');
    scwin.setSymblDataSet(dtsObj, 10, '하나은행4우선주', 'HNBA');
    scwin.setSymblDataSet(dtsObj, 11, '하나은행5우선주', 'HNBB');
};

/**
 * @method
 * @name setSymblDataSet
 * @description 영문심볼 안내 데이터 행 추가
 * @param {*} dtsObj dtsObj
 * @param {Number} idx idx
 * @param {*} val_1 val_1
 * @param {*} val_2 val_2
 * @returns {void}
 * @hidden N
 */
scwin.setSymblDataSet = function (dtsObj, idx, val_1, val_2) {
    dtsObj.insertRow();
    dtsObj.setCellData(idx, "isuKorNm", val_1);
    dtsObj.setCellData(idx, "isuEngSymbl", val_2);
};

/**
 * @method
 * @name setShrtCdGrid
 * @description 단축코드 안내 그리드 데이터 구성(보통주/신주 코드표)
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
