 * @hidden N
 */
scwin.setShrtCdGrid = function (grdObj, dtsObj) {
    // var vHeadString = "STKCERT_KIND_CD:STRING(500),STKCERT_KIND_NM:STRING(500),ISU_SRT_CD:STRING(500)";
    // dtsObj.SetDataHeader(vHeadString);
    scwin.setShrtCdDataSet(dtsObj, 0, '보통주', '000', '0');
    scwin.setShrtCdDataSet(dtsObj, 1, '보통1신주', '001', '1');
    scwin.setShrtCdDataSet(dtsObj, 2, '보통2신주', '002', '2');
    scwin.setShrtCdDataSet(dtsObj, 3, '보통3신주', '003', '3');
    scwin.setShrtCdDataSet(dtsObj, 4, '보통4신주', '004', '4');
    scwin.setShrtCdDataSet(dtsObj, 5, '1우선주', '100', '5');
    scwin.setShrtCdDataSet(dtsObj, 6, '1우선주(신주)', '101', '6');
    scwin.setShrtCdDataSet(dtsObj, 7, '2우선주', '200', '7');
    scwin.setShrtCdDataSet(dtsObj, 8, '2우선주(신주)', '201', '8');
    scwin.setShrtCdDataSet(dtsObj, 9, '3우선주', '300', '9');
    scwin.setShrtCdDataSet(dtsObj, 10, '4우선주', '400', 'A');
    scwin.setShrtCdDataSet(dtsObj, 11, '5우선주', '500', 'B');
};

/**
 * @method
 * @name setShrtCdDataSet
 * @description 단축코드 안내 데이터 행 추가
 * @param {*} dtsObj dtsObj
 * @param {Number} idx idx
 * @param {*} val_1 val_1
 * @param {*} val_2 val_2
 * @param {*} val_3 val_3
 * @returns {void}
 * @hidden N
 */
scwin.setShrtCdDataSet = function (dtsObj, idx, val_1, val_2, val_3) {
    dtsObj.insertRow();
    dtsObj.setCellData(idx, "stkcertKindCd", val_1);
    dtsObj.setCellData(idx, "stkcertKindNm", val_2);
    dtsObj.setCellData(idx, "isuSrtCd", val_3);
};
